const DOMAINS=[['General Security Concepts',12],['Threats, Vulnerabilities & Mitigations',22],['Security Architecture',18],['Security Operations',28],['Security Program Management & Oversight',20]];
const LESSONS=[];const QUESTIONS=[];
function unit(id,title,summary,points,example,trap,qs){LESSONS.push({id,title,summary,points,example,trap,domain:Number(id[0])-1});qs.forEach((q,i)=>QUESTIONS.push({id:id+'-'+i,lesson:id,domain:Number(id[0])-1,prompt:q[0],options:q[1],explanations:q[2],answer:0}));}
unit('1.1','Choose the right security control','Describe a control along two axes: how it is implemented and what it does. One control can have several effects.',[
'Categories: technical controls are enforced by technology; managerial controls govern decisions and policy; operational controls rely on people and processes; physical controls protect facilities and equipment.',
'Functions: preventive blocks an event; detective identifies it; corrective restores or fixes; deterrent discourages; directive tells people what to do; compensating provides an alternative when the preferred control is infeasible.',
'Classify the function stated in the scenario. A camera recording evidence is detective; its visible presence may also deter. An access policy can be managerial and directive.'
],'A managed endpoint policy blocks unsigned applications. The technology makes it technical; blocking execution makes it preventive.','Do not confuse the implementation category with the control function.',[
['A badge reader denies entry to an unauthorized visitor. Which function is demonstrated?',['Preventive','Detective','Corrective','Directive'],['It stops unauthorized entry before it occurs.','Logging an entry attempt would detect it.','Corrective controls repair damage after an event.','A written instruction directs behavior; the reader enforces access.']],
['A legacy system cannot support MFA. Access is restricted to a monitored jump host with MFA and tightly controlled accounts. What is this alternative?',['Compensating control','Risk avoidance','Deterrent control only','Control removal'],['An alternative mitigates the gap left by an unavailable primary control.','Avoidance would stop the risky activity altogether.','The jump host enforces access rather than merely discouraging misuse.','Additional safeguards have been introduced, not removed.']]]);
unit('1.2','CIA, AAA & zero trust','Security decisions protect confidentiality, integrity and availability. Identity decisions authenticate a subject, authorize an action and account for what happened.',[
'Confidentiality prevents unauthorized disclosure. Integrity protects against improper change. Availability keeps systems and data usable when needed. Non-repudiation provides evidence tying an action to its originator.',
'Authentication asks who you are; authorization asks what you may do; accounting records activity. A successful sign-in does not imply permission to access every resource.',
'Zero trust avoids implicit trust based on network location. A policy engine decides, a policy administrator establishes or terminates access, and a policy enforcement point allows or blocks traffic. Verify explicitly and limit privilege.',
'Physical defenses include access vestibules, bollards and sensors. Deception tools such as honeypots and honeytokens create monitored decoys. Gap analysis compares the current state with the required state.'
],'A staff member signs in successfully but cannot open the payroll folder. Authentication succeeded; authorization is restricting access.','Zero trust does not mean denying every request or trusting every internal device.',[
['An attacker silently changes a patient appointment record. Which property is primarily harmed?',['Integrity','Availability','Confidentiality','Non-repudiation'],['The unauthorized alteration damages correctness.','Availability concerns whether the record can be accessed.','Disclosure would primarily affect confidentiality.','Attribution is not the primary issue described.']],
['A laptop is on the corporate LAN. Under zero trust, how should an application grant access?',['Evaluate identity, device state and policy','Trust the device because it is internal','Grant access after a ping response','Disable authentication on the LAN'],['Network location alone is insufficient; assess the request.','An internal location is not proof of trustworthiness.','Reachability does not prove identity or permission.','Removing authentication contradicts explicit verification.']]]);
unit('1.3','Make changes safely','A good security change is approved, tested, scheduled, documented and reversible. Assess business impact before touching production.',[
'Identify the owner, affected stakeholders, dependencies and approval path. Define scope, impact, test evidence and a maintenance window.',
'Prepare a backout plan with clear triggers. Service restarts, downtime, legacy dependencies and allow-list changes can turn a small change into an outage.',
'Update diagrams, procedures and version-controlled configurations after implementation. Emergency changes still need an authorized emergency process and retrospective documentation.'
],'Before changing a firewall rule, test the application path, record the current configuration and define how to restore it if users lose access.','A successful lab test does not replace change approval or a backout plan.',[
['A firewall change may disconnect remote clinics. Which preparation best supports rapid recovery if it fails?',['A tested backout plan','A new awareness poster','A longer password policy','Deleting the old configuration'],['A tested reversal minimizes downtime after a failed change.','Awareness does not restore network connectivity.','Password policy is unrelated to reverting the change.','Deleting the prior configuration removes a recovery option.']],
['An emergency patch is needed on a production server. What is the best approach?',['Use the authorized emergency change process','Skip all approval and documentation','Wait indefinitely for a normal window','Disable logging to speed up installation'],['Emergency procedures balance urgency with accountability.','Urgency does not remove the need for oversight and records.','Indefinite delay leaves an active risk untreated.','Disabling logging reduces visibility and does not ensure a safe patch.']]]);
unit('1.4','Encryption, hashing & certificates','Encryption protects confidentiality; hashing produces a digest; digital signatures support integrity and origin authentication. They solve different problems.',[
'Symmetric encryption uses a shared key and is efficient for bulk data. Asymmetric cryptography uses a public/private key pair for functions such as signatures and key establishment.',
'A cryptographic hash is one-way and fixed-length. Store passwords with a unique salt and a deliberately slow password hashing scheme. Salting defeats reuse of precomputed hash tables; it does not encrypt passwords.',
'A certificate binds a public key to a subject through an issuer signature. Validate trust chain, hostname, dates and revocation status as appropriate. The private key must remain secret.',
'A digital signature is created with the signer’s private key and verified with their public key. TPMs and HSMs protect key material. Tokenization substitutes a value; obfuscation only makes data harder to interpret.'
],'Full-disk encryption protects a stolen powered-off laptop. It does not prevent a signed-in user or malware from accessing data the session can already read.','A hash is not reversible encryption. A valid certificate is not a guarantee that a business is trustworthy.',[
['You must prove that a software update came from the publisher and was not altered. What best provides both?',['A verified digital signature','Base64 encoding','Encryption without authentication','A filename containing “official”'],['A signature binds the content to the signing key and exposes changes.','Encoding is reversible formatting, not proof of origin.','Encryption alone does not establish publisher authenticity.','A filename is freely changeable.']],
['Two users have the same password. What prevents identical stored password hashes when properly implemented?',['A unique random salt per password','The same global salt for everyone','Reversible Base64 encoding','Removing password hashing'],['Unique salts cause identical passwords to produce different stored results.','A shared salt would still yield identical results for identical passwords.','Encoding does not securely store passwords.','Plaintext password storage exposes credentials.']]]);
unit('2.1','Threat actors & motivations','Distinguish who could attack, why they would do it, and what resources they have. Avoid identifying an actor from one technical indicator alone.',[
'Nation-state actors may pursue espionage or disruption with substantial resources. Organized crime commonly pursues financial gain. Hacktivists pursue ideological goals.',
'Insider threats involve legitimate access, whether malicious or unintentional. Unskilled attackers can still cause damage using available tooling. Shadow IT introduces unmanaged systems without necessarily being malicious.',
'Assess resources, sophistication, intent and access. Motives include extortion, revenge, data theft, service disruption and geopolitical advantage.'
],'A former administrator retains an active account and downloads confidential records. The access history points to an insider access risk.','Sophisticated malware alone does not prove a nation-state actor.',[
['An employee deliberately sells internal customer data using their approved access. Which actor category fits?',['Malicious insider','Unintentional outsider','Security auditor by definition','Only a nation-state'],['The employee abuses legitimate internal access.','The behavior is deliberate and performed by an insider.','Audit access does not authorize selling data.','No evidence establishes state involvement.']],
['A group threatens to publish stolen files unless a company pays. Which motivation is most evident?',['Financial gain through extortion','Routine asset inventory','Business continuity testing','Accidental misconfiguration'],['The demand for payment is evidence of extortion.','Inventory does not involve threatening publication.','A legitimate continuity test would be authorized.','A deliberate ransom demand is not accidental.']]]);
unit('2.2','Attack surfaces & social engineering','An attack surface is the set of possible exposure points. An attack vector is the path used to reach a target.',[
'Exposure can come from email, messages, voice calls, removable media, insecure networks, vulnerable software, open ports or the supply chain. Reducing the surface removes unnecessary entry points.',
'Phishing uses deceptive messages; spear phishing targets a person or group; whaling targets senior leaders; smishing uses text messages; vishing uses voice. Business email compromise exploits trusted business communications.',
'Pretexting creates a believable story; impersonation adopts an identity. Watering-hole attacks compromise a site targets visit. Typosquatting relies on look-alike domain spelling. Verify sensitive requests through a known independent channel.'
],'A message appears to be from a supervisor and asks you to bypass purchasing rules. Call the supervisor using a known directory number, not the number in the message.','Urgency and authority cues are reasons to verify, not reasons to skip verification.',[
['A caller claims to be the help desk and asks for an MFA code. What is the delivery technique?',['Vishing','Smishing','On-path interception','SQL injection'],['The lure is delivered through a voice call.','Smishing uses SMS or text messages.','The scenario describes deception, not traffic interception.','SQL injection targets database queries.']],
['A finance employee receives a request from a familiar executive email account to change bank details. What is the best immediate action?',['Verify through a known independent channel','Reply asking whether the email is real','Use the phone number in the email','Pay because the sender address matches'],['Independent verification protects against compromised accounts.','An attacker controlling the mailbox could also answer the reply.','The supplied number may belong to the attacker.','A familiar account can be compromised.']]]);
unit('2.3','Recognize vulnerabilities','A vulnerability is a weakness. An exploit uses it. A threat is a potential cause of harm, and risk considers likelihood and impact.',[
'Software flaws include memory safety failures, race conditions and injection. In a time-of-check/time-of-use race, a resource changes after validation but before use.',
'Misconfiguration, default credentials, unsupported software, insecure protocols and missing patches create exposure. Rooting or jailbreaking may undermine mobile security controls.',
'Cloud, virtualized and supply-chain systems add shared dependencies. VM escape crosses a virtualization isolation boundary. A zero-day vulnerability lacks an available fix or is newly unknown to the relevant defender/vendor context.'
],'A public storage bucket contains internal documents. The immediate weakness is an access configuration problem, even if no attacker has yet accessed it.','A high severity score is not the same as confirmed exploitation in your environment.',[
['A web application combines untrusted form input directly into database queries. Which weakness is most directly implicated?',['SQL injection','ARP poisoning','RF interference','Tailgating'],['Untrusted input changes the meaning of a database command.','ARP poisoning affects local network address resolution.','Radio interference affects wireless availability.','Tailgating is a physical entry technique.']],
['A server still uses a vendor-default administrator password. What is the primary vulnerability?',['Insecure configuration','A proven zero-day exploit','Mandatory access control','Strong key management'],['Unchanged default credentials are a configuration weakness.','No unknown software flaw is necessary.','Access-control models do not describe the weakness here.','Default passwords do not constitute strong key management.']]]);
unit('2.4','Read signs of an attack','Indicators are evidence to investigate. Combine multiple sources before declaring what happened.',[
'Ransomware denies access and may accompany data theft. Trojans disguise malicious functionality; worms self-propagate; rootkits hide activity; spyware collects information.',
'Password spraying tries a few common passwords against many accounts. Brute force tries many guesses; credential stuffing reuses stolen username/password pairs. Repeated MFA prompts may indicate fatigue abuse.',
'On-path attacks intercept communications; replay reuses a captured message; DNS poisoning changes resolution. DDoS exhausts availability with distributed traffic.',
'Application attacks include injection and cross-site scripting. Privilege escalation gains greater rights; lateral movement reaches other systems. Unusual logins, blocked accounts and unexpected outbound transfers are clues, not complete attribution.'
],'Hundreds of users each have one failed sign-in from the same source using a common password. This pattern suggests password spraying.','A single failed sign-in is not proof of compromise; look for patterns and subsequent success.',[
['One IP tries “Winter2026!” against 200 different user accounts. What is the best classification?',['Password spraying','Credential stuffing','Single-account brute force','A replay of a signed transaction'],['A small password set is being tried across many users.','Stuffing uses previously stolen account/password pairs.','The defining pattern here spreads attempts across accounts.','No captured transaction is being replayed.']],
['A signed-in user’s browser executes attacker-supplied script from a comment field. What attack is illustrated?',['Stored cross-site scripting','SQL injection','DNS tunneling','Physical tailgating'],['Malicious content is stored and later executed in a browser.','Database command manipulation is not described.','DNS is not the channel involved.','This is not a physical access event.']]]);
unit('2.5','Reduce exposure with layered defenses','Match the mitigation to the weakness. Layer controls so that one failure does not expose everything.',[
'Segmentation limits communication and lateral movement. Isolation restricts a specific device or workload. Least privilege limits the actions an identity can take.',
'Hardening removes unnecessary services, changes defaults, patches software and secures settings. Application allow-listing permits known applications; deny-listing blocks known unwanted items.',
'Monitoring detects suspicious activity, while patching removes known software weaknesses. Decommission unsupported assets and document approved exceptions when immediate remediation is impossible.'
],'A vulnerable printer cannot be patched immediately. Restrict it to the print server, remove internet access and monitor it while planning replacement.','Segmentation reduces reachability; it does not fix the underlying software bug.',[
['An unsupported device must remain temporarily. Which control best limits lateral movement from it?',['Network segmentation with restrictive rules','Rename the device','Disable all security logging','Give it domain administrator access'],['Restricting communication reduces the systems it can reach.','A new name does not change attack paths.','Removing logs reduces visibility.','Elevated privilege increases potential impact.']],
['Only approved business executables should run on managed laptops. Which control fits?',['Application allow-listing','Disk defragmentation','A larger DHCP scope','Open guest Wi-Fi'],['Allow-listing restricts execution to authorized software.','Defragmentation does not authorize software.','Address capacity does not control execution.','Guest network access is unrelated to executable approval.']]]);
unit('3.1','Architecture & shared responsibility','Architecture determines where controls live, who operates them and which failures can spread.',[
'On-premises environments give the organization broad operational responsibility. Cloud IaaS leaves guest OS and application management to the customer; PaaS shifts more platform work to the provider; SaaS shifts application operation too.',
'The exact shared responsibility split depends on the service and agreement. Customers still govern identities, permissions, data use and configuration within their control.',
'Virtual machines isolate operating systems; containers normally share a host kernel. Serverless shifts server operations to a provider but leaves customer code and permissions in scope.',
'Consider IaC, microservices, edge devices, OT/ICS and embedded systems. Legacy industrial equipment may prioritize safety, reliability and uptime, constraining patching and active scanning.'
],'A hosted EHR provider patches its platform, while the organization still removes departed users and assigns access roles.','Moving to SaaS does not transfer every security responsibility to the provider.',[
['A team deploys an operating system on a cloud IaaS VM. Who normally patches the guest OS?',['The customer','The provider in every IaaS service','The certificate authority','The ISP'],['Guest operating system maintenance normally remains a customer duty in IaaS.','The provider manages underlying infrastructure, not automatically every guest OS.','A CA issues certificates, not OS patches.','An ISP provides connectivity.']],
['Why should an active vulnerability scan of a legacy industrial controller be coordinated with its owner?',['The scan could disrupt a safety-critical process','Industrial systems never have vulnerabilities','Scanning automatically patches the device','Ownership removes the need for authorization'],['Fragile operational systems may react badly to scanning.','Industrial systems can have serious vulnerabilities.','Discovery does not remediate the findings.','Owner coordination and authorization are essential.']]]);
unit('3.2','Secure the network path','Place controls at the point where they can inspect or enforce the relevant traffic. Start with required communication, then deny unnecessary paths.',[
'A firewall enforces traffic rules; an IDS detects and alerts; an IPS can block inline. A WAF focuses on web application requests. A proxy intermediates connections.',
'Use segmentation and controlled interfaces between trust zones. A DMZ hosts services exposed externally while limiting access to internal systems. VPNs protect traffic in transit; they do not make compromised endpoints trustworthy.',
'802.1X provides port-based network access control using an authentication framework. NAC can evaluate device identity and posture. Secure Wi-Fi with appropriate enterprise authentication and modern encryption.',
'Know where a control fails: fail-open preserves traffic flow if the control fails, while fail-closed denies it. Balance availability with security and safety requirements.'
],'Guest Wi-Fi clients should reach the internet but not internal administration interfaces. Put them in a separate zone with explicit restrictions.','A VLAN alone is not a complete security policy; inter-VLAN traffic must be controlled.',[
['Which control is specifically designed to filter malicious HTTP requests targeting a web application?',['WAF','UPS','Password vault','Full-disk encryption'],['A web application firewall inspects web-layer requests.','A UPS provides backup power.','A vault manages secrets.','Disk encryption protects stored data.']],
['A security sensor must actively block malicious traffic in its path. Which capability is required?',['Inline IPS','Passive IDS only','Offline archive','A read-only asset list'],['An inline prevention system can stop traffic.','A passive detector alerts without directly blocking the path.','An archive is for retained data.','An asset list cannot enforce traffic decisions.']]]);
unit('3.3','Protect data throughout its life','Classify data by sensitivity and business impact, then select controls for where it is stored, transmitted and used.',[
'Data at rest is stored, data in transit is moving and data in use is being processed. Encryption scope and key access must fit the state and threat.',
'Classification labels guide handling. Data owners decide classification and access requirements; custodians implement handling controls. Minimization collects only what is needed and retention limits how long it remains.',
'DLP identifies and restricts sensitive data movement. Masking obscures values for display; tokenization replaces them with references; encryption transforms them using keys.',
'Data sovereignty concerns jurisdictional authority over data. Location and contractual requirements matter when choosing storage regions and service providers.'
],'A reporting dataset replaces client identifiers with tokens. The mapping is stored separately with tighter access than the report.','Encryption does not eliminate access governance, retention or location requirements.',[
['A laptop is stolen while powered off. Which safeguard most directly protects locally stored files from offline reading?',['Full-disk encryption with protected keys','A screen privacy filter','A longer monitor timeout','A public inventory entry'],['Encryption protects stored contents when the attacker lacks the keys.','A privacy filter reduces shoulder surfing, not offline disk access.','Timeout settings do not encrypt the storage.','Inventory supports tracking, not data confidentiality.']],
['A team wants to detect and block uploads containing sensitive records. Which technology best fits?',['Data loss prevention','Load balancing','RAID mirroring','DHCP reservation'],['DLP can inspect data and apply exfiltration policies.','Load balancing distributes workload.','RAID supports storage availability.','DHCP reservations stabilize network addressing.']]]);
unit('3.4','Resilience, backups & recovery','Plan for failures before they happen. Recovery targets describe business needs; tests show whether your design can meet them.',[
'RTO is the target time to restore a service. RPO is the maximum tolerable data loss measured in time. A four-hour RPO needs recoverable data no more than four hours old at the disruption.',
'High availability reduces downtime through redundant components and failover. Load balancing distributes work. Neither replaces a backup protected from deletion and ransomware.',
'Backups may be full, incremental or differential. Test actual restoration, including dependencies and access to keys. Offline or immutable copies reduce exposure to production compromise.',
'Hot recovery sites are ready quickly; warm sites need some preparation; cold sites need more provisioning. Consider power, geographic separation, staffing and communication dependencies.'
],'A service has a two-hour RTO and a fifteen-minute RPO: restore service within two hours and lose no more than fifteen minutes of data.','RTO is downtime; RPO is data loss. Replication can copy corruption just as quickly as good data.',[
['The business can tolerate losing at most 30 minutes of transactions. Which target is being defined?',['RPO','RTO','MTTR','Annualized loss expectancy'],['RPO specifies the acceptable time span of lost data.','RTO specifies time to restore the service.','MTTR is an observed or estimated average repair duration.','ALE is an annual risk estimate in monetary units.']],
['A company mirrors production data continuously. Why does it still need protected backups?',['Corruption and deletion can replicate too','Mirroring always encrypts all files','Replication guarantees clean history forever','Backups only improve CPU speed'],['A separate recoverable history protects against replicated bad changes.','Encryption does not follow automatically from mirroring.','Replication alone does not guarantee historical recovery.','Backup purpose is recoverability, not CPU performance.']]]);
unit('4.1','Harden endpoints & applications','Build a secure baseline, apply it consistently and detect drift. A baseline is a starting configuration, not proof that a device will remain secure.',[
'Endpoint hardening includes patching, local privilege reduction, host firewalls, disk encryption, secure boot and disabling unnecessary services. MDM manages mobile and endpoint configuration.',
'Application security includes input validation, secure cookies, code review and dependency management. Parameterized database queries separate data from commands.',
'Wireless and mobile controls include certificate-based enterprise authentication, managed configuration and separation of work data where supported. BYOD, COPE and fully corporate ownership imply different privacy and control boundaries.'
],'An Intune compliance policy reports that a device is noncompliant; a connected access policy is what can deny access based on that state.','Reporting a problem and enforcing a restriction are separate capabilities.',[
['What best prevents SQL injection in an application’s database calls?',['Parameterized queries','Hiding the login page URL','Changing the web server wallpaper','Disabling audit logs'],['Parameters keep untrusted values separate from query structure.','Hidden URLs are still discoverable.','Appearance has no bearing on database safety.','Removing logs does not prevent injection.']],
['Which action most directly reduces damage from everyday user accounts being compromised?',['Remove unnecessary local administrator rights','Assign every user a shared admin password','Disable automatic locking','Allow all unsigned software'],['Least privilege limits the actions a stolen account can perform.','Shared privileged access increases impact and weakens accountability.','Unlocked sessions increase access risk.','Unrestricted execution increases exposure.']]]);
unit('4.2','Track assets from arrival to disposal','You cannot reliably secure assets you do not know you have. Inventory must include ownership, software, data sensitivity and lifecycle state.',[
'Procurement should consider support lifetime, supply-chain risk and security requirements. Assign an accountable owner and track hardware, software and licensing.',
'Inventory and enumeration identify what exists. Monitoring identifies changes, unsupported software and assets that are no longer managed.',
'Disposal requires suitable sanitization or destruction, verification and records. The method depends on media technology, sensitivity and reuse plans. Deleting files or quick formatting usually does not securely sanitize a drive.'
],'A retired laptop is tracked by serial number through approved sanitization, verification and disposal. Its asset record is then closed.','A missing device in an inventory is not automatically a securely disposed device.',[
['An old SSD containing confidential data will leave the organization. What is the best approach?',['Use an approved, verified sanitization or destruction process','Delete the desktop shortcuts','Quick-format it and assume all data is gone','Remove only the asset sticker'],['The process must address the actual media and verify the result.','Shortcuts are pointers, not the underlying files.','Quick formatting does not reliably sanitize the media.','Labels do not protect stored data.']],
['A newly discovered server has no recorded owner or support status. What should happen first?',['Identify and inventory it with an accountable owner','Assume it is safe because it is online','Delete its logs','Grant it unrestricted outbound access'],['Ownership and inventory support meaningful risk assessment and remediation.','Availability is not evidence of security.','Logs may be needed to understand the asset.','Unrestricted access increases exposure.']]]);
unit('4.3','Prioritize & validate vulnerabilities','Vulnerability management is a cycle: identify, analyze, prioritize, remediate or mitigate, validate and report.',[
'Credentialed scans can inspect installed software and local configuration. Uncredentialed scans show exposure from a more limited perspective. Penetration testing attempts to validate exploitability within an authorized scope.',
'Prioritize severity alongside active exploitation, internet exposure, asset criticality and available mitigations. A lower scored vulnerability on a critical exposed system may be more urgent than a higher scored isolated finding.',
'Investigate false positives, assign owners and track deadlines. After remediation, rescan or otherwise verify that the weakness is resolved. Exceptions need approval and review.'
],'A remotely exploitable internet gateway flaw with active exploitation takes priority over an isolated test machine with a higher score but no reachable attack path.','A scan report is not proof of remediation, and CVSS alone is not a business priority list.',[
['Which finding should generally receive the most urgent attention?',['An actively exploited flaw on an exposed critical gateway','An equally severe flaw on a powered-off disposable lab VM','A cosmetic issue on an internal wiki','An expired bookmark'],['Exposure, exploitation and criticality combine to create immediate risk.','An offline disposable VM has less immediate reachability and impact.','A cosmetic issue lacks the stated exploitation risk.','A bookmark is not the critical vulnerability described.']],
['An administrator reports that a patch is installed. What closes the remediation loop?',['Validate with a rescan or equivalent verification','Delete the finding without checking','Turn off the scanner permanently','Change the finding title'],['Verification confirms that the vulnerability is actually resolved.','A reported action can fail or be incomplete.','Stopping scans removes visibility.','Renaming a finding does not fix it.']]]);
unit('4.4','Turn telemetry into useful alerts','Logs record events. Monitoring looks for meaningful patterns. Good detection depends on coverage, timing and context.',[
'A SIEM centralizes and correlates security events. EDR focuses on endpoint telemetry and response. SOAR coordinates and automates response workflows.',
'Collect relevant identity, endpoint, network and application logs. Synchronize clocks so events can be correlated. Protect logs against tampering and limit access.',
'Tune thresholds and detections to reduce false positives without ignoring true threats. Alert fatigue grows when low-value notifications overwhelm analysts.'
],'Correlate a suspicious cloud sign-in with an endpoint alert and unusual downloads instead of investigating each signal in isolation.','A SIEM is not automatically an inline blocking device.',[
['You need to correlate sign-in, firewall and endpoint events in one place. What best fits?',['SIEM','A UPS','A standalone cable tester','A disk partition tool'],['A SIEM aggregates and correlates events across sources.','A UPS addresses power continuity.','Cable testing does not correlate application and identity logs.','Partitioning disks does not analyze events.']],
['Two systems report conflicting event times during an investigation. Which preventive measure improves future correlation?',['Reliable clock synchronization','Random time zones per server','Disabling timestamps','Removing audit logs'],['Consistent time allows events from different systems to be ordered.','Unmanaged time settings complicate interpretation.','Missing timestamps destroy useful chronology.','Deleting logs removes evidence.']]]);
unit('4.5','Operate security controls','Controls need ongoing configuration, review and tuning. A product purchase is not the same as an effective defense.',[
'Review firewall and filtering rules for necessity, scope and order. Remove obsolete access and apply an explicit default policy.',
'DNS filtering, email filtering, endpoint protection and file integrity monitoring cover different parts of the environment. SPF authorizes email senders; DKIM signs messages; DMARC applies alignment-based policy and reporting.',
'Secure baselines, operating system policy and DLP settings require exception management. Test control changes and monitor for unexpected business impact.'
],'A firewall has an early allow-any rule. A later deny rule cannot undo that match in a first-match ruleset.','A narrowly written rule is ineffective if a broader earlier rule already allows the traffic.',[
['In a first-match firewall, an allow-any rule comes before a deny rule for an untrusted source. What happens?',['The earlier allow rule matches and permits the traffic','The last rule always wins','All rules are averaged','The deny rule always takes precedence regardless of order'],['First-match processing stops at the first applicable rule.','Last-match processing is a different model.','Rules are not averaged.','A deny rule does not override an earlier match in the stated model.']],
['Which email mechanism publishes policy for messages failing aligned SPF or DKIM checks?',['DMARC','DHCP','NTP','SNMP'],['DMARC uses alignment with authenticated domains and publishes handling/reporting policy.','DHCP assigns network configuration.','NTP synchronizes clocks.','SNMP supports device monitoring and management.']]]);
unit('4.6','Identity, access & privilege','Manage identities through joiner, mover and leaver events. Give each identity the access it needs for the time it needs it.',[
'Provisioning creates and grants access; deprovisioning removes it. Regular access reviews catch privilege accumulation, stale accounts and inappropriate role membership.',
'MFA combines different factor types: something you know, have or are. Two passwords are still one factor type. Phishing-resistant authentication can bind authentication to the legitimate service.',
'RBAC grants permissions through job roles; ABAC evaluates attributes and context. Least privilege reduces permissions; separation of duties divides sensitive tasks. PAM governs privileged access, and just-in-time access limits its duration.',
'SSO reduces repeated sign-ins; federation establishes trust across identity domains. LDAP is a directory protocol; SAML and OpenID Connect support federated sign-in; OAuth is primarily delegated authorization.'
],'A technician uses a standard account for daily work and requests time-limited elevation for approved administration.','MFA is not “two steps of any kind.” Two knowledge secrets do not provide two factor types.',[
['Which pair uses two different authentication factor types?',['Password and hardware security key','Password and PIN','PIN and security question','Two different passwords'],['A password is something you know; the key is something you have.','Both are knowledge factors.','Both rely on knowledge.','Both are the same factor type.']],
['A technician receives administrator rights only for an approved 30-minute task. What is this?',['Just-in-time privileged access','Permanent standing privilege','Shared anonymous access','Discretionary public access'],['Elevation exists only during the authorized window.','Standing privilege persists beyond the immediate task.','The access is attributable and time-bound.','No public resource access is described.']]]);
unit('4.7','Automate with guardrails','Automation handles repeatable work; orchestration connects tasks across systems. Both require controlled permissions and reliable failure handling.',[
'Useful applications include provisioning, enrichment, ticket creation, baseline enforcement and containment. Start with a clear trigger, action and expected outcome.',
'Service accounts and API credentials should have narrow permissions. Store secrets securely, validate inputs and audit actions. Test workflows against realistic failure cases.',
'High-impact actions may need human approval. Watch for false positives, error propagation, dependency failure and single points of failure. Define rollback and escalation paths.'
],'A workflow enriches a suspicious sign-in with device and identity context, then asks an analyst to approve disabling a critical service account.','Faster execution amplifies bad logic as well as good logic.',[
['A new detection sometimes produces false positives. Before allowing it to disable critical accounts automatically, what is the best safeguard?',['Add approval and test the workflow','Give the automation global admin forever','Remove all audit records','Trigger it on every login'],['Approval and testing reduce the impact of incorrect detections.','Broad permanent privilege increases the blast radius.','Records are essential for accountability and troubleshooting.','Every login is not evidence of compromise.']],
['A response workflow needs to read alerts and create tickets. Which account design fits least privilege?',['Grant only the required API permissions','Use a shared domain administrator account','Embed a personal password in the script','Disable authentication for the API'],['Narrow permissions support the required actions while reducing risk.','Domain admin is far broader than the workflow requires.','Personal embedded secrets are difficult to govern safely.','Unauthenticated access would expose the system.']]]);
unit('4.8','Respond to incidents & preserve evidence','Follow the organization’s response plan. Validate and scope the event, contain the threat, remove its cause, recover safely and learn from it.',[
'Preparation includes roles, communication, playbooks, tooling and exercises. Detection and analysis establish what happened and what is affected. Containment limits ongoing harm.',
'Eradication removes persistence and root causes. Recovery restores trustworthy service and monitors for recurrence. Lessons learned feed improvements back into preparation.',
'Preserve relevant evidence and document who handled it, when and why. Chain of custody supports evidence integrity and accountability. Volatile data may disappear when power is removed.',
'Legal holds preserve relevant records. Forensic acquisition should follow approved methods; evidence handling must not delay urgent actions required to protect people or stop severe harm.'
],'An endpoint is actively encrypting shared files. Isolate it through approved controls, notify the response team and preserve evidence using the incident procedure.','Blindly wiping or rebooting a suspect device can destroy evidence before the incident is understood.',[
['A workstation is actively encrypting network shares. What is the best immediate containment action within your authority?',['Isolate it from the network and activate the response process','Wait for the nightly backup','Wipe every server immediately','Post the logs publicly'],['Isolation limits spread while the response process coordinates investigation.','Waiting allows ongoing damage.','Indiscriminate wiping is destructive and can remove evidence.','Public disclosure is not containment and may expose sensitive data.']],
['What documents possession and handling of forensic evidence?',['Chain of custody','A marketing calendar','A password hint','An uptime graph alone'],['It records transfers, handlers and relevant timestamps.','Marketing schedules do not establish evidence handling.','Password hints are unrelated.','Availability graphs do not document custody.']]]);
unit('4.9','Investigate with the right data','Choose evidence that can answer the specific question. Logs, flows and packet captures offer different levels of detail.',[
'Authentication logs show sign-ins, failures and identity context. Endpoint logs show process and system activity. Application logs reveal operations the application recorded.',
'Network flow data summarizes connections and volumes; packet captures can expose protocol details and unencrypted payloads. Encrypted traffic limits visible payload content without authorized decryption.',
'Use baselines to recognize anomalies. Correlate independent sources, preserve originals and record investigation steps. A missing event may reflect a logging gap rather than proof that nothing happened.'
],'To investigate an unusual upload, combine proxy or firewall flows with endpoint process records and identity events.','An IP address alone does not identify a person, and encrypted packet captures do not automatically reveal application contents.',[
['You need the process that launched an unexpected executable on a laptop. Which source is most direct?',['Endpoint process telemetry','A building floor plan','A DHCP lease alone','A printer toner report'],['Process telemetry can show parent-child execution relationships.','A floor plan does not record software execution.','DHCP can map an address but not explain the process tree.','Printer supply data is irrelevant.']],
['A flow record shows a large outbound connection. What can it usually establish without packet contents?',['Connection metadata and transferred volume','The exact plaintext of encrypted files','The attacker’s legal identity','Proof that every byte was malicious'],['Flow records summarize who communicated, when and how much.','Encrypted payload contents are not automatically available.','Network metadata alone does not establish legal identity.','Volume is an investigative clue, not proof of malicious content.']]]);
unit('5.1','Policies, standards & governance','Governance defines direction, authority and accountability. Operational documents turn that direction into consistent action.',[
'A policy states management intent and requirements. A standard specifies mandatory rules. A procedure gives repeatable steps. A guideline recommends an approach.',
'Assign owners, approvers and review schedules. Governance structures should make accountability clear across internal teams, suppliers and business leadership.',
'Important policies include acceptable use, access control, data handling, change management and business continuity. Update them when business, technology or obligations change.'
],'A password policy requires strong authentication; a standard defines approved methods; a procedure explains how to enroll a user.','A procedure explains how; a policy explains required direction and intent.',[
['Which document gives the exact steps to disable a departing employee’s accounts?',['Procedure','High-level policy only','Optional guideline only','Risk appetite statement'],['A procedure provides the repeatable operational sequence.','A policy establishes requirements rather than every action.','Optional advice does not define the required workflow.','Risk appetite expresses tolerance, not account actions.']],
['An organization mandates a specific approved encryption configuration. Which document type best captures that technical requirement?',['Standard','Informal suggestion','Meeting invitation','Press release'],['A standard states mandatory implementation requirements.','A suggestion is not mandatory.','An invitation does not define technical requirements.','Public announcements are not configuration standards.']]]);
unit('5.2','Risk decisions & business impact','Risk connects uncertainty to business consequences. Decisions should reflect impact, likelihood, costs and the organization’s tolerance.',[
'Risk responses: avoid stops the activity; mitigate reduces likelihood or impact; transfer shifts some financial consequences through contracts or insurance; accept retains the risk through an authorized decision.',
'Quantitative analysis uses numbers. SLE = asset value × exposure factor. ALE = SLE × annualized rate of occurrence. Qualitative analysis uses defined categories such as low, medium and high.',
'A risk register records risk descriptions, owners, responses and status. Inherent risk is before controls; residual risk remains after controls.',
'A business impact analysis identifies critical services and disruption effects, informing recovery priorities. Risk appetite describes broad willingness to take risk; tolerance sets more specific boundaries.'
],'A $100,000 asset with 20% loss per incident has a $20,000 SLE. At 0.25 incidents per year, ALE is $5,000.','Insurance does not eliminate the event or automatically transfer every operational and reputational consequence.',[
['An incident causes $40,000 in loss and is expected once every four years. What is the ALE?',['$10,000','$160,000','$40,000','$4,000'],['$40,000 × 0.25 incidents per year = $10,000 per year.','That multiplies by four instead of the annual frequency.','That is the loss per event, not per year.','Once every four years is 0.25, not 0.1.']],
['Leadership formally approves retaining a low-impact risk without additional controls. Which response is this?',['Acceptance','Avoidance','Transfer','Eradication'],['An authorized decision retains the risk.','Avoidance stops the activity that creates the risk.','Transfer shifts some consequences to another party.','Eradication is an incident response activity, not this risk decision.']]]);
unit('5.3','Manage supplier risk','A vendor can create exposure through its access, software, data handling or dependencies. Due diligence starts before contracting and continues afterward.',[
'Assess security practices, relevant audit evidence, incident history, subcontractors and data handling. A questionnaire is one input, not conclusive proof of security.',
'Contracts should address responsibilities, access, notification, data return/deletion and the right to assess controls. Monitor material changes and reassess periodically.',
'An SLA defines service targets; an NDA covers confidentiality; an MSA sets broad commercial terms; an SOW describes scoped work. Rules of engagement define authorized testing boundaries.'
],'Before using a hosted service, review how it protects data, notifies you of incidents and returns or deletes data when the relationship ends.','A signed contract does not remove the need to verify performance and security over time.',[
['Which agreement is best suited to define uptime and response-time commitments?',['SLA','NDA','Password policy','Chain of custody'],['A service-level agreement specifies service commitments.','An NDA addresses confidentiality.','A password policy governs authentication requirements.','Chain of custody concerns evidence handling.']],
['Before a third party performs penetration testing, what must be clearly agreed?',['Authorization, scope and rules of engagement','Only the tester’s preferred wallpaper','Permission to attack any supplier without limits','A plan to publish credentials'],['Testing requires explicit boundaries and authorization.','Appearance is unrelated to authorized testing.','One organization cannot automatically authorize attacks on unrelated suppliers.','Publishing credentials is not a testing prerequisite.']]]);
unit('5.4','Compliance, privacy & accountability','Compliance means meeting applicable obligations. Security reduces risk. They overlap, but passing an assessment does not prove every risk is controlled.',[
'Obligations may arise from laws, regulations, contracts or internal policy. Identify applicability with appropriate owners and legal expertise, then retain evidence of required controls.',
'Privacy concerns appropriate collection, use, retention and sharing of personal data. Minimize data, define purpose and manage access. Roles such as controller and processor depend on the applicable framework.',
'Noncompliance may create fines, contractual consequences or reputational damage. Reporting and notification requirements depend on the jurisdiction and facts; do not assume one deadline fits every incident.'
],'An organization documents who can access sensitive records, why access is needed, how access is reviewed and how long records must remain.','Checking a compliance box does not guarantee that a system is secure against every threat.',[
['A form collects birth dates even though the business process does not need them. Which principle suggests removing the field?',['Data minimization','Privilege escalation','Load distribution','Availability clustering'],['Collect only the personal data needed for the defined purpose.','Escalation increases access, not privacy protection.','Load distribution concerns system performance.','Clustering concerns resilience.']],
['An audit found no compliance exceptions. What is the most accurate conclusion?',['The assessed requirements were met within the audit scope','No attack can ever succeed','Every untested system is secure','Risk management is no longer necessary'],['Audit conclusions are bounded by scope, evidence and time.','No audit guarantees immunity to attacks.','Untested systems are outside the evidence base.','Risk changes and still requires management.']]]);
unit('5.5','Audits, assessments & exercises','Match an assessment method to the question you need answered. Independence, scope and evidence shape the strength of its conclusions.',[
'An audit checks evidence against defined criteria. An assessment evaluates a security posture. A penetration test attempts authorized exploitation to validate impact.',
'Internal reviews provide organizational insight; external reviews can provide independent assurance. Attestation communicates an assertion supported through a defined process.',
'Known-environment tests give testers extensive information; unknown-environment tests provide little; partially known tests sit between them. Define scope and constraints for each.',
'Red teams simulate adversaries; blue teams defend; purple-team collaboration improves detection and response. Findings should lead to accountable remediation and retesting.'
],'A vulnerability scanner reports an outdated service; an authorized penetration test may show whether it can actually be exploited within the approved scope.','A scan and a penetration test are not interchangeable.',[
['A tester receives network diagrams, credentials and source code. Which testing perspective fits?',['Known-environment testing','Unknown-environment testing','A purely passive public survey','No authorized testing'],['The tester starts with extensive internal knowledge.','Unknown-environment testing supplies little internal information.','Credentials and source code go beyond a passive public survey.','The information level does not imply lack of authorization.']],
['Defenders and offensive testers collaborate to improve detection using simulated attacks. Which approach is this?',['Purple teaming','Uncoordinated production sabotage','Asset disposal','Risk transfer through insurance'],['Purple teaming links attack simulation with defensive improvement.','The collaboration is authorized and improvement-focused.','Disposal concerns asset retirement.','Insurance is a different risk response.']]]);
unit('5.6','Build a security-aware culture','Training should help people recognize a risky situation and take a specific safe action. Measure behavior, not just attendance.',[
'Teach recognition of phishing, unusual requests, unsafe data handling and physical access risks. Give staff a simple reporting path and encourage prompt reporting.',
'Tailor training to roles and threats. Use onboarding, recurring reinforcement and appropriate exercises. Sensitive roles may need more specific scenarios.',
'Measure reporting rates, report speed, repeat patterns and improvement over time. A simulation click rate is one signal and should not be used alone to shame people or declare success.'
],'A staff member reports an unexpected MFA prompt. A quick, supportive response helps contain risk and encourages future reporting.','Punishing honest mistakes can drive incidents underground.',[
['Which outcome most directly shows that a phishing awareness program improved response behavior?',['Faster and more frequent reporting of suspicious messages','More posters printed','Longer slide decks','Higher email storage quotas'],['Reporting behavior is an operational outcome of awareness.','Printed material measures activity, not safer behavior.','Content length is not evidence of effectiveness.','Storage quotas are unrelated to recognizing phishing.']],
['A user clicked a suspicious link and reports it immediately. What response best supports the security program?',['Thank them, gather facts and follow the response process','Shame them publicly','Tell them to keep quiet','Delete the report without review'],['Supportive handling encourages timely reporting and enables containment.','Public blame discourages future reporting.','Silence delays response and hides risk.','The report may identify a real incident.']]]);
const MATCHSETS=[{title:'Control functions',pairs:[['Preventive','Blocks an unwanted event'],['Detective','Identifies an event'],['Corrective','Repairs damage or restores service'],['Compensating','Provides an alternative safeguard'],['Deterrent','Discourages an unwanted action'],['Directive','States required behavior']]},{title:'Security operations',pairs:[['SIEM','Correlates events across sources'],['EDR','Provides endpoint detection and response'],['SOAR','Orchestrates response workflows'],['DLP','Restricts sensitive data movement'],['WAF','Filters web application requests'],['PAM','Governs privileged access']]},{title:'Risk & recovery',pairs:[['RTO','Target time to restore service'],['RPO','Acceptable data loss measured in time'],['SLE','Expected loss from one event'],['ALE','Expected loss per year'],['Residual risk','Risk remaining after controls'],['Risk transfer','Shifts some consequences to another party']]},{title:'Cryptography',pairs:[['Hashing','Produces a one-way digest'],['Symmetric encryption','Uses a shared secret key'],['Digital signature','Supports integrity and origin authentication'],['Certificate','Binds a public key to a subject'],['Salt','Makes identical passwords hash differently'],['Tokenization','Replaces a value with a reference token']]}];
